<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import AppIcon from '../../components/AppIcon.vue'
import { adminApi, publicApi } from '../../api/services.js'
import { useSeo } from '../../composables/useSeo.js'
import { useToast } from '../../composables/useToast.js'
import { formatMoney, orderSourceLabel, orderStatusLabel, paymentStatusLabel } from '../../utils/format.js'

const router=useRouter(),toast=useToast(),saving=ref(false),error=ref(''),products=ref([]),config=ref({shipping_methods:[],payment_methods:[]})
const form=reactive({customer_name:'',customer_phone:'',customer_email:'',source:'manual',shipping_method:'',shipping_city:'',shipping_branch:'',shipping_address:'',shipping_carrier:'',payment_method:'',customer_note:'',admin_note:'',discount_amount:0,shipping_amount:0,status:'new',payment_status:'unpaid',items:[]})
const selectedShipping=computed(()=>config.value.shipping_methods?.find(x=>x.code===form.shipping_method)||null)
const subtotal=computed(()=>form.items.reduce((sum,row)=>{const p=products.value.find(x=>x.slug===row.product_slug);return sum+(p?.price_minor||0)*Number(row.quantity||0)},0))
const total=computed(()=>Math.max(0,subtotal.value-Math.round(Number(form.discount_amount||0)*100)+Math.round(Number(form.shipping_amount||0)*100)))
useSeo({title:'New order | Velmora Admin',description:'Create an order manually.',path:'/admin/orders/new',noindex:true})
function addItem(){const p=products.value.find(x=>!form.items.some(i=>i.product_slug===x.slug));if(p)form.items.push({product_slug:p.slug,quantity:1})}
function removeItem(i){form.items.splice(i,1)}
async function load(){try{const [p,c]=await Promise.all([adminApi.products({page:1,size:100,active:true}),publicApi.config()]);products.value=p.items||[];config.value=c;form.shipping_method=c.shipping_methods?.[0]?.code||'';form.payment_method=c.payment_methods?.[0]?.code||'';form.shipping_amount=(c.shipping_methods?.[0]?.price_minor||0)/100;addItem()}catch{error.value='Could not load order data.'}}
function shippingChanged(){const m=selectedShipping.value;form.shipping_amount=(m?.price_minor||0)/100;form.shipping_carrier=m?.carrier||''}
async function submit(){if(!form.items.length){error.value='Add at least one product.';return}saving.value=true;error.value='';try{const order=await adminApi.createOrder({customer_name:form.customer_name,customer_phone:form.customer_phone,customer_email:form.customer_email||null,source:form.source,items:form.items.map(x=>({product_slug:x.product_slug,quantity:Number(x.quantity)})),shipping_method:form.shipping_method||null,shipping_city:form.shipping_city||null,shipping_branch:form.shipping_branch||null,shipping_address:form.shipping_address||null,shipping_carrier:form.shipping_carrier||null,payment_method:form.payment_method||null,customer_note:form.customer_note||null,admin_note:form.admin_note||null,discount_minor:Math.round(Number(form.discount_amount||0)*100),shipping_minor:Math.round(Number(form.shipping_amount||0)*100),status:form.status,payment_status:form.payment_status});toast.show(`Order ${order.order_number} created.`);router.push(`/admin/orders/${order.id}`)}catch(e){error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:'Could not create the order.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><section class="admin-page admin-order-create"><div class="admin-page-head"><div><p>MANUAL ORDER</p><h1 class="ui-display">New order</h1><span>For orders received by phone, Telegram, Viber, Instagram or other channels.</span></div></div><form class="admin-order-create-grid" @submit.prevent="submit"><div class="admin-order-create-main"><section class="admin-panel admin-editor-section"><div class="admin-panel-head"><div><small>CUSTOMER</small><h2>Contact details</h2></div></div><div class="admin-form-grid"><label class="admin-field"><span>Name</span><input v-model="form.customer_name" required maxlength="160"></label><label class="admin-field"><span>Phone</span><input v-model="form.customer_phone" required maxlength="32"></label><label class="admin-field"><span>Email</span><input v-model="form.customer_email" type="email" maxlength="320"></label><label class="admin-field"><span>Source</span><select v-model="form.source"><option v-for="s in ['manual','phone','telegram','viber','instagram','other']" :key="s" :value="s">{{orderSourceLabel(s)}}</option></select></label></div></section>
<section class="admin-panel admin-editor-section"><div class="admin-panel-head"><div><small>ITEMS</small><h2>Order items</h2></div><button type="button" @click="addItem">+ Add product</button></div><div class="admin-order-items"><div v-for="(row,i) in form.items" :key="i" class="admin-order-item"><select v-model="row.product_slug"><option v-for="p in products" :key="p.slug" :value="p.slug">{{p.title}} — {{formatMoney(p.price_minor,p.currency)}}</option></select><input v-model.number="row.quantity" type="number" min="1" max="99"><button type="button" @click="removeItem(i)">×</button></div></div></section>
<section class="admin-panel admin-editor-section"><div class="admin-panel-head"><div><small>SHIPPING & PAYMENT</small><h2>Order terms</h2></div></div><div class="admin-form-grid"><label class="admin-field"><span>Shipping</span><select v-model="form.shipping_method" @change="shippingChanged"><option value="">Not selected</option><option v-for="m in config.shipping_methods" :key="m.code" :value="m.code">{{m.name}}</option></select></label><label class="admin-field"><span>Payment</span><select v-model="form.payment_method"><option value="">Not selected</option><option v-for="m in config.payment_methods" :key="m.code" :value="m.code">{{m.name}}</option></select></label><label v-if="selectedShipping?.requires_city" class="admin-field"><span>City</span><input v-model="form.shipping_city"></label><label v-if="selectedShipping?.requires_branch" class="admin-field"><span>Branch</span><input v-model="form.shipping_branch"></label><label v-if="selectedShipping?.requires_address" class="admin-field admin-field--wide"><span>Address</span><input v-model="form.shipping_address"></label><label class="admin-field"><span>Carrier</span><input v-model="form.shipping_carrier"></label><label class="admin-field"><span>Shipping amount</span><input v-model.number="form.shipping_amount" type="number" min="0"></label><label class="admin-field"><span>Discount amount</span><input v-model.number="form.discount_amount" type="number" min="0"></label></div></section>
<section class="admin-panel admin-editor-section"><div class="admin-panel-head"><div><small>STATUS</small><h2>Processing</h2></div></div><div class="admin-form-grid"><label class="admin-field"><span>Status</span><select v-model="form.status"><option v-for="s in ['new','confirmed','processing','shipped','completed','cancelled','returned']" :key="s" :value="s">{{orderStatusLabel(s)}}</option></select></label><label class="admin-field"><span>Payment</span><select v-model="form.payment_status"><option v-for="s in ['unpaid','pending','paid','refunded']" :key="s" :value="s">{{paymentStatusLabel(s)}}</option></select></label><label class="admin-field admin-field--wide"><span>Customer note</span><textarea v-model="form.customer_note" rows="3"></textarea></label><label class="admin-field admin-field--wide"><span>Internal note</span><textarea v-model="form.admin_note" rows="3"></textarea></label></div></section></div>
<aside class="admin-order-create-side"><div class="admin-panel admin-order-summary"><div class="admin-panel-head"><div><small>SUMMARY</small><h2>Total</h2></div></div><dl><div><dt>Products</dt><dd>{{formatMoney(subtotal)}}</dd></div><div><dt>Shipping</dt><dd>{{formatMoney(Math.round(form.shipping_amount*100))}}</dd></div><div><dt>Discount</dt><dd>−{{formatMoney(Math.round(form.discount_amount*100))}}</dd></div><div class="is-total"><dt>Total</dt><dd>{{formatMoney(total)}}</dd></div></dl><div v-if="error" class="admin-alert">{{error}}</div><button class="btn btn-primary" type="submit" :disabled="saving"><AppIcon name="cart"/>{{saving?'Creating…':'Create order'}}</button></div></aside></form></section></template>
